import React, { useState, useCallback, useMemo } from 'react';
import {
  ProgressBar,
  ProgressSlider,
  StatusBadge,
  PriorityBadge,
  RiskBadge,
  ConfirmationDialog,
} from './ui-components';
import {
  EpicStatus, // Used for StatusBadge prop type
  StoryStatus, // Used for StatusBadge prop type
  Priority, // Used for PriorityBadge prop type and createStory default
  RiskLevel, // Used for RiskBadge prop type
  StoryPoints, // Used for display and createStory default
  EpicEntity, // For type inference in signature
  StoryEntity, // For type inference in signature
} from './domain';

// Helper to format enum values for display (e.g., "NOT_STARTED" -> "Not Started")
const formatEnum = (value) => {
  if (value == null) return '';
  return String(value).replace(/_/g, ' ').toLowerCase().replace(/\b\w/g, (char) => char.toUpperCase());
};

export default function BacklogPresentation({
  epics = [],
  stories = [],
  epicLogic,
  storyLogic,
  notificationService,
  onAddNewEpic,
}) {
  const [expandedEpics, setExpandedEpics] = useState(new Set());
  const [showConfirmationDialog, setShowConfirmationDialog] = useState(false);
  const [entityToDelete, setEntityToDelete] = useState(null); // { type: 'epic' | 'story', id: string, code: string, title: string }
  const [addingStoryToEpicId, setAddingStoryToEpicId] = useState(null); // string | null
  const [editingEntity, setEditingEntity] = useState(null); // { type: 'epic' | 'story', id: string }

  const handleExpandEpic = useCallback((epicId) => {
    setExpandedEpics((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(epicId)) {
        newSet.delete(epicId);
      } else {
        newSet.add(epicId);
      }
      return newSet;
    });
  }, []);

  const handleUpdateStoryProgress = useCallback(async (storyId, progress) => {
    try {
      await storyLogic.updateStoryProgress(storyId, progress);
      notificationService.ShowSuccess('Story progress updated successfully.');
      // The parent component is expected to re-fetch and pass updated epics/stories props
      // to trigger a re-render with the latest data.
    } catch (error) {
      notificationService.ShowError(`Failed to update story progress: ${error.message}`);
    }
  }, [storyLogic, notificationService]);

  const handleEditEntity = useCallback((entityType, id) => {
    setEditingEntity({ type: entityType, id });
    // In a real application, this would typically open a modal or navigate to an edit page.
    // For this exercise, we simulate the opening and a successful update.
    notificationService.ShowInfo(`Opening edit form for ${formatEnum(entityType)} ID: ${id}`);
  }, [notificationService]);

  const handleDeleteEntity = useCallback((entityType, id, code, title) => {
    setEntityToDelete({ type: entityType, id, code, title });
    setShowConfirmationDialog(true);
  }, []);

  const handleConfirmDelete = useCallback(async () => {
    if (!entityToDelete) return;

    const { type, id, title } = entityToDelete;
    try {
      if (type === 'epic') {
        await epicLogic.deleteEpic(id);
      } else if (type === 'story') {
        await storyLogic.deleteStory(id);
      }
      notificationService.ShowSuccess(`${formatEnum(type)} "${title}" deleted successfully.`);
      // The parent component is expected to re-fetch and pass updated epics/stories props
      // to trigger a re-render with the latest data.
    } catch (error) {
      notificationService.ShowError(`Failed to delete ${type}: ${error.message}`);
    } finally {
      setShowConfirmationDialog(false);
      setEntityToDelete(null);
    }
  }, [entityToDelete, epicLogic, storyLogic, notificationService]);

  const handleCancelDelete = useCallback(() => {
    setShowConfirmationDialog(false);
    setEntityToDelete(null);
  }, []);

  const handleToggleBlocked = useCallback(async (entityType, id) => {
    try {
      let entity;
      if (entityType === 'epic') {
        entity = epics.find(e => e.id === id);
      } else if (entityType === 'story') {
        entity = stories.find(s => s.id === id);
      }

      if (!entity) {
        throw new Error(`${formatEnum(entityType)} not found.`);
      }

      const newBlockedState = !entity.isBlocked;
      const action = newBlockedState ? 'blocked' : 'unblocked';

      if (entityType === 'epic') {
        await epicLogic.updateEpic(id, { isBlocked: newBlockedState });
      } else if (entityType === 'story') {
        await storyLogic.updateStory(id, { isBlocked: newBlockedState });
      }
      notificationService.ShowSuccess(`${formatEnum(entityType)} "${entity.title}" is now ${action}.`);
      // The parent component is expected to re-fetch and pass updated epics/stories props
      // to trigger a re-render with the latest data.
    } catch (error) {
      notificationService.ShowError(`Failed to toggle blocked status: ${error.message}`);
    }
  }, [epics, stories, epicLogic, storyLogic, notificationService]);

  const handleAddStoryInline = useCallback(async (epicId, title) => {
    setAddingStoryToEpicId(epicId);
    if (!title || !title.trim()) {
      notificationService.ShowWarning("Story title cannot be empty.");
      setAddingStoryToEpicId(null);
      return;
    }
    try {
      // In a real app, formData would come from the inline form inputs.
      // For this demo, we use a minimal placeholder and default values.
      await storyLogic.createStory(epicId, {
        title: formData.title || 'New Story',
        description: '',
        priority: Priority.MEDIUM,
        storyPoints: StoryPoints.ONE,
        assignee: 'Unassigned',
        sprint: 'Backlog',
        plannedStartDate: new Date().toISOString().split('T')[0],
        plannedEndDate: new Date().toISOString().split('T')[0],
        jiraRef: '',
        notes: '',
        externalLinks: [],
      });
      notificationService.ShowSuccess('Story added successfully.');
      setAddingStoryToEpicId(null); // Hide form
      // The parent component is expected to re-fetch and pass updated epics/stories props
      // to trigger a re-render with the latest data.
    } catch (error) {
      notificationService.ShowError(`Failed to add story: ${error.message}`);
    }
  }, [storyLogic, notificationService]);

  // Group stories by epic for efficient rendering
  const storiesByEpic = useMemo(() => {
    return stories.reduce((acc, story) => {
      if (!acc[story.epicId]) {
        acc[story.epicId] = [];
      }
      acc[story.epicId].push(story);
      return acc;
    }, {});
  }, [stories]);

  return (
    <div className="p-4">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-bold">Project Backlog</h2>
        <button onClick={onAddNewEpic} className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700">
          Add New Epic
        </button>
      </div>
      <div className="overflow-x-auto">
        <table className="min-w-full bg-white border border-gray-200">
          <thead>
            <tr className="bg-gray-100 text-left text-sm font-semibold text-gray-600 uppercase tracking-wider">
              <th className="py-2 px-4 border-b"></th> {/* Expand/Collapse */}
              <th className="py-2 px-4 border-b">Code</th>
              <th className="py-2 px-4 border-b">Title</th>
              <th className="py-2 px-4 border-b">Quarter/Year</th>
              <th className="py-2 px-4 border-b">Priority</th>
              <th className="py-2 px-4 border-b">Risk</th>
              <th className="py-2 px-4 border-b">Owner</th>
              <th className="py-2 px-4 border-b">Progress</th>
              <th className="py-2 px-4 border-b">Status</th>
              <th className="py-2 px-4 border-b">Jira Ref</th>
              <th className="py-2 px-4 border-b">Actions</th>
            </tr>
          </thead>
          <tbody>
            {epics.length === 0 && (
              <tr>
                <td colSpan="11" className="py-4 px-4 text-center text-gray-500">No epics found.</td>
              </tr>
            )}
            {epics.map((epic) => (
              <React.Fragment key={epic.id}>
                <tr className="border-b hover:bg-gray-50">
                  <td className="py-2 px-4">
                    <button
                      onClick={() => handleExpandEpic(epic.id)}
                      className="text-blue-600 hover:text-blue-800 focus:outline-none"
                    >
                      {expandedEpics.has(epic.id) ? '▼' : '▶'}
                    </button>
                  </td>
                  <td className="py-2 px-4 font-medium">{epic.code}</td>
                  <td className="py-2 px-4">{epic.title}</td>
                  <td className="py-2 px-4">{epic.quarter} {epic.year}</td>
                  <td className="py-2 px-4">
                    <PriorityBadge priority={epic.priority} />
                  </td>
                  <td className="py-2 px-4">
                    <RiskBadge risk={epic.riskLevel} />
                  </td>
                  <td className="py-2 px-4">{epic.owner}</td>
                  <td className="py-2 px-4">
                    <ProgressBar value={epic.progress} />
                  </td>
                  <td className="py-2 px-4">
                    <StatusBadge status={epic.status} />
                  </td>
                  <td className="py-2 px-4">{epic.jiraRef}</td>
                  <td className="py-2 px-4 space-x-2 flex flex-wrap gap-1">
                    <button
                      onClick={() => handleEditEntity('epic', epic.id)}
                      className="text-indigo-600 hover:text-indigo-900 text-sm"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => handleDeleteEntity('epic', epic.id, epic.code, epic.title)}
                      className="text-red-600 hover:text-red-900 text-sm"
                    >
                      Delete
                    </button>
                    <button
                      onClick={() => handleToggleBlocked('epic', epic.id)}
                      className={`text-sm ${epic.isBlocked ? 'text-green-600 hover:text-green-900' : 'text-yellow-600 hover:text-yellow-900'}`}
                    >
                      {epic.isBlocked ? 'Unblock' : 'Block'}
                    </button>
                    <button
                      onClick={() => setAddingStoryToEpicId(epic.id)}
                      className="text-blue-600 hover:text-blue-900 text-sm"
                    >
                      Add Story
                    </button>
                  </td>
                </tr>
                {expandedEpics.has(epic.id) && storiesByEpic[epic.id]?.map((story) => (
                  <tr key={story.id} className="bg-gray-50 border-b hover:bg-gray-100">
                    <td className="py-2 px-4 pl-8"></td> {/* Indent for stories */}
                    <td className="py-2 px-4 text-sm">{story.code}</td>
                    <td className="py-2 px-4 text-sm">{story.title}</td>
                    <td className="py-2 px-4 text-sm" colSpan="2">{story.assignee} / {story.sprint}</td>
                    <td className="py-2 px-4 text-sm">
                      <PriorityBadge priority={story.priority} />
                    </td>
                    <td className="py-2 px-4 text-sm">{story.storyPoints} SP</td>
                    <td className="py-2 px-4 text-sm">
                      <ProgressSlider
                        value={story.progress}
                        onChange={(newValue) => handleUpdateStoryProgress(story.id, newValue)}
                        isDisabled={story.isBlocked}
                      />
                    </td>
                    <td className="py-2 px-4 text-sm">
                      <StatusBadge status={story.status} />
                    </td>
                    <td className="py-2 px-4 text-sm">{story.jiraRef}</td>
                    <td className="py-2 px-4 space-x-2 flex flex-wrap gap-1">
                      <button
                        onClick={() => handleEditEntity('story', story.id)}
                        className="text-indigo-600 hover:text-indigo-900 text-sm"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => handleDeleteEntity('story', story.id, story.code, story.title)}
                        className="text-red-600 hover:text-red-900 text-sm"
                      >
                        Delete
                      </button>
                      <button
                        onClick={() => handleToggleBlocked('story', story.id)}
                        className={`text-sm ${story.isBlocked ? 'text-green-600 hover:text-green-900' : 'text-yellow-600 hover:text-yellow-900'}`}
                      >
                        {story.isBlocked ? 'Unblock' : 'Block'}
                      </button>
                    </td>
                  </tr>
                ))}
                {/* Inline Add Story Form (Conceptual) */}
                {addingStoryToEpicId === epic.id && (
                  <tr className="bg-gray-100">
                    <td colSpan="11" className="py-2 px-4">
                      <div className="flex items-center space-x-2">
                        <input
                          type="text"
                          placeholder="Story Title"
                          className="border p-1 rounded text-sm flex-grow"
                          id={`new-story-title-${epic.id}`} // Added ID for direct access in demo
                          onKeyDown={(e) => { if (e.key === 'Enter') handleAddStoryInline(epic.id, e.target.value); }}
                        />
                        <button
                          onClick={() => handleAddStoryInline(epic.id, document.getElementById(`new-story-title-${epic.id}`)?.value || '')}
                          className="bg-blue-500 text-white px-3 py-1 rounded text-sm hover:bg-blue-600"
                        >
                          Save Story
                        </button>
                        <button
                          onClick={() => setAddingStoryToEpicId(null)}
                          className="bg-gray-300 text-gray-800 px-3 py-1 rounded text-sm hover:bg-gray-400"
                        >
                          Cancel
                        </button>
                      </div>
                    </td>
                  </tr>
                )}
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>

      {showConfirmationDialog && entityToDelete && (
        <ConfirmationDialog
          message={`Are you sure you want to delete ${formatEnum(entityToDelete.type)} "${entityToDelete.title}" (${entityToDelete.code})? This action cannot be undone.`}
          onConfirm={handleConfirmDelete}
          onCancel={handleCancelDelete}
        />
      )}

      {/* Conceptual Edit Modal (not fully implemented, just state and basic UI) */}
      {editingEntity && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded shadow-lg w-1/2">
            <h3 className="text-xl font-bold mb-4">Edit {formatEnum(editingEntity.type)}</h3>
            <p className="mb-4">
              Editing {editingEntity.type} with ID: {editingEntity.id}.
              In a real application, a dedicated form component with actual inputs would be rendered here.
            </p>
            <div className="mt-4 flex justify-end space-x-2">
              <button
                onClick={() => {
                  setEditingEntity(null);
                  notificationService.ShowSuccess(`${formatEnum(editingEntity.type)} updated successfully.`);
                  // Parent component is expected to re-fetch and pass updated epics/stories
                }}
                className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600"
              >
                Save (Demo)
              </button>
              <button
                onClick={() => setEditingEntity(null)}
                className="bg-gray-300 text-gray-800 px-4 py-2 rounded hover:bg-gray-400"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}